def add(kind,n,page,note,parts,domain,rep='text'):
 direct=sorted({d for p in parts for d in p.get('assessed_8227_demand_ids',[])})
 components=sorted({d for p in parts for d in p.get('component_demand_ids',[])}-set(direct))
 inputs=[p.get('original_function',p.get('source_quantity_model'))for p in parts if p.get('original_function')or p.get('source_quantity_model')]
 r=o.h.add(kind,n,page,note,parts,direct,components,powers=inputs)
